async function call<T>(
	client: HostClientLike,
	operation: string,
	input: unknown,
	options: HostInvokeOptions | undefined,
	acceptInput: (value: unknown, strict?: boolean) => boolean,
	acceptOutput: (value: unknown) => boolean,
): Promise<T> {
	if (input !== undefined && !acceptInput(input, true)) {
		throw new QgisSdkHostContractError(operation, "the arguments do not match the declared request");
	}
	const value = await client.invoke(
		operation,
		(input ?? {}) as Readonly<Record<string, unknown>>,
		options,
	);
	if (!acceptOutput(value)) {
		throw new QgisSdkHostContractError(operation, "the response does not match the declared result");
	}
	return value as T;
}

async function open<E extends { readonly kind: string }>(
	client: HostClientLike,
	operation: string,
	input: unknown,
	handlers: HostStreamHandlers<E>,
	options: HostInvokeOptions | undefined,
	acceptInput: (value: unknown, strict?: boolean) => boolean,
	acceptEvent: (value: unknown) => value is E,
): Promise<HostStreamHandle> {
	if (!acceptInput(input, true)) {
		throw new QgisSdkHostContractError(operation, "the arguments do not match the declared request");
	}
	// The typed stream ends exactly once, like the subscription under it: a
	// contract violation ends it here, closes the subscription, and the
	// `disposed` the client then reports is not delivered a second time.
	let ended = false;
	let violated = false;
	let handle: HostStreamHandle | null = null;
	const end = (terminal: HostStreamTerminal): void => {
		if (ended) return;
		ended = true;
		handlers.onTerminal?.(terminal);
	};
	handle = await client.subscribe(
		operation,
		input as Readonly<Record<string, unknown>>,
		{
			onEvent: (event) => {
				if (ended) return;
				if (acceptEvent(event)) {
					handlers.onEvent?.(event);
					return;
				}
				end({
					kind: "error",
					message: new QgisSdkHostContractError(
						operation,
						"an event does not match the declared events",
					).message,
				});
				if (handle === null) {
					violated = true;
				} else {
					handle.close();
				}
			},
			onTerminal: end,
		},
		options,
	);
	if (violated) {
		handle.close();
	}
	return handle;
}
